    fn macro_arguments<'a>(source: &'a str, token: &str) -> Vec<Vec<&'a str>> {
        let mut calls = Vec::new();
        for (start, _) in source.match_indices(token) {
            let begin = start + token.len();
            let mut field = begin;
            let mut fields = Vec::new();
            let mut stack = vec![b')'];
            let mut quoted = false;
            let mut escaped = false;
            let mut comment = false;
            let bytes = source.as_bytes();
            let mut at = begin;
            while !stack.is_empty() {
                assert!(at < bytes.len(), "unterminated production macro");
                let byte = bytes[at];
                if comment {
                    if byte == b'\n' {
                        comment = false;
                    }
                } else if quoted {
                    if escaped {
                        escaped = false;
                    } else if byte == b'\\' {
                        escaped = true;
                    } else if byte == b'"' {
                        quoted = false;
                    }
                } else {
                    match byte {
                        b'/' if bytes.get(at + 1) == Some(&b'/') => comment = true,
                        b'"' => quoted = true,
                        b'(' => stack.push(b')'),
                        b'[' => stack.push(b']'),
                        b'{' => stack.push(b'}'),
                        b')' | b']' | b'}' => {
                            assert_eq!(stack.pop(), Some(byte));
                            if stack.is_empty() {
                                let last = source[field..at].trim();
                                if !last.is_empty() {
                                    fields.push(last);
                                }
                            }
                        }
                        b',' if stack.len() == 1 => {
                            fields.push(source[field..at].trim());
                            field = at + 1;
                        }
                        _ => {}
                    }
                }
                at += 1;
            }
            calls.push(fields);
        }
        calls
    }
